{
  "name": "@tiuxo/opencode-git-trailer",
  "version": "0.2.1",
  "description": "Adds a configurable git commit trailer (e.g. Assisted-by: <model>) to commits opencode makes, without touching your own git usage.",
  "type": "module",
  "license": "BSD-3-Clause",
  "author": "brian",
  "repository": {
    "type": "git",
    "url": "git+https://git.tiuxo.com/brian/opencode-git-trailer.git"
  },
  "homepage": "https://git.tiuxo.com/brian/opencode-git-trailer",
  "bugs": {
    "url": "https://git.tiuxo.com/brian/opencode-git-trailer/issues"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "git",
    "git-trailer",
    "commit",
    "attribution",
    "provenance"
  ],
  "publishConfig": {
    "access": "public",
    "registry": "https://registry.npmjs.org/"
  },
  "exports": {
    ".": "./index.ts"
  },
  "files": [
    "index.ts",
    "src",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "test": "bun test",
    "typecheck": "tsc --noEmit",
    "check": "bun run typecheck && bun test"
  },
  "devDependencies": {
    "@opencode/plugin": "^2.1.3",
    "@types/bun": "^1.4.4",
    "typescript": "^5.8.2"
  },
  "engines": {
    "opencode": ">=2.0.0"
  }
}
